my @types=qw(Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare Reaction User UserIdentity UserSetting); my(%hit,%dot);
for my $f (@ARGV){next if $f =~ m{^store(?:/|$)}; open my $h,"<",$f or die $!; local $/; my $s=<$h>; my $dir=$f; $dir =~ s{/[^/]+$}{}; my @aliases;
while($s =~ /import\s+(?:([A-Za-z_][A-Za-z0-9_]*|[.])\s+)?"github[.]com\/usememos\/memos\/store"/g){push @aliases,defined($1)?$1:"store"}
while($s =~ /import\s*\((.*?)\)/sg){my $b=$1; while($b =~ /^\s*(?:([A-Za-z_][A-Za-z0-9_]*|[.])\s+)?"github[.]com\/usememos\/memos\/store"/mg){push @aliases,defined($1)?$1:"store"}}
next unless @aliases; my $clean=$s; $clean =~ s{/[*].*?[*]/}{}sg; $clean =~ s{//[^\n]*}{}g; $clean =~ s{"(?:\\.|[^"\\])*"}{""}sg; $clean =~ s{`[^`]*`}{``}sg;
for my $a (@aliases){if($a eq "."){$dot{$dir}=1;next} for my $t (@types){$hit{$t}{$dir}=1 if $clean =~ /\b\Q$a\E\s*[.]\s*\Q$t\E\b/}}
}
for my $t (@types){my @p=sort keys %{$hit{$t}//{}}; print "$t\t".scalar(@p)."\t".join(",",@p)."\n"} print "DOT\t".join(",",sort keys %dot)."\n";
' **/*.go

